arguments.command:
python3 << 'EOF'
import csv
from collections import Counter

rows = []
with open('/app/benchmark/data.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['Year'].strip():
            rows.append({'Year': int(row['Year']), 'Film': row['Film'], 'Composer': row['Composer']})

# First time wins by year (for a composer who had won before)
first_wins = {}
for r in rows:
    c = r['Composer']
    if c not in first_wins:
        first_wins[c] = r['Year']

# Gap between first and last win
print("Longest gaps between first and last win:")
composer_years = {}
for r in rows:
    c = r['Composer']
    if c not in composer_years:
        composer_years[c] = []
    composer_years[c].append(r['Year'])

gaps = [(c, max(yrs)-min(yrs), min(yrs), max(yrs)) for c, yrs in composer_years.items() if len(yrs) > 1]
gaps.sort(key=lambda x: -x[1])
for c, gap, first, last in gaps[:10]:
    print(f"  {c}: {gap} years ({first}–{last})")

# All data for the full table
print("\nAll data by decade:")
for r in sorted(rows, key=lambda x: x['Year']):
    print(f"{r['Year']},{r['Composer']},{r['Film']}")

EOF

